# DEMO 1: Analyze all connected components
def find_connected_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = {}  # color -> list of component cell lists

    for color in set(x for row in grid for x in row):
        components[color] = []

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if visited[r][c]:
                continue
            if (r, c) in components[color][-1]:
                continue

            component = []
            queue = [(r, c)]
            while queue:
                cr, cc = queue.pop(0)
                if visited[cr][cc]:
                    continue
                visited[cr][cc] = True
                component.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                        if grid[nr][nc] == color:
                            queue.append((nr, nc))

            components[color].append(component) if not (component and visited[cr][cc]) or len(component) == 0 else None

    return components

