    """
    Transform the grid based on the observed patterns.
    The input has background 7s with various patterns.
    We change the background 7 to 0 and keep other values.
    """
    result = [row[:] for row in grid]
    for i in range(len(result)):
        for j in range(len(result[i])):
            if result[i][j] == 7:
                result[i][j] = 0
    return result

